<?php require_once __DIR__.'/_header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$n=trim($_POST['name']);if($n){$s=slugify($n);db()->prepare('INSERT IGNORE INTO categories(name,slug) VALUES(?,?)')->execute([$n,$s]);}}$rows=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();?><h1>Categories</h1><form method="post" class="card"><?=csrf_field()?><input name="name" placeholder="Category name" required><button>Add</button></form><table><tr><th>Name</th><th>Slug</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slug'])?></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';